public async Task<Dictionary<int, int>> GetTotalViewsByBlogIdAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into g
        select new { BlogId = g.Key, TotalViews = g.Sum(p => p.Views) };

    var result = await query.ToDictionaryAsync(
        x => x.BlogId,
        x => x.TotalViews,
        cancellationToken);

    return result;
}
```

